import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_min_dim1(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math_constants.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_min_dim1_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int B,
    int R,
    int C)
{
    const int b = static_cast<int>(blockIdx.y);
    const int c = static_cast<int>(blockIdx.x) * blockDim.x + threadIdx.x;

    if (b >= B || c >= C) {
        return;
    }

    auto input = make_tensor(
        make_gmem_ptr(x),
        make_shape(B, R, C),
        make_stride(R * C, C, 1));

    auto output = make_tensor(
        make_gmem_ptr(out),
        make_shape(B, C),
        make_stride(C, 1));

    float best = CUDART_INF_F;

    for (int r = 0; r < R; ++r) {
        const float value = input(b, r, c);

        if (isnan(value) ||
            value < best ||
            (value == best &&
             signbit(value) &&
             !signbit(best))) {
            best = value;
        }
    }

    output(b, c) = best;
}

torch::Tensor cute_min_dim1(torch::Tensor x)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat,
        "cute_min_dim1 currently supports float32 tensors only");

    auto x_contiguous = x.contiguous();

    const int B = static_cast<int>(x_contiguous.size(0));
    const int R = static_cast<int>(x_contiguous.size(1));
    const int C = static_cast<int>(x_contiguous.size(2));

    auto out = torch::empty(
        {static_cast<int64_t>(B), static_cast<int64_t>(C)},
        x_contiguous.options());

    constexpr int threads = 256;
    dim3 block(threads);
    dim3 grid(
        (C + threads - 1) / threads,
        B);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_min_dim1_kernel<<<grid, block, 0, stream>>>(
        x_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        R,
        C);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE min reduction kernel launch failed");

    return out;
}
"""

cute_ext = load_inline(
    name="cute_min_dim1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_min_dim1"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.dim not in (1, -2):
            raise ValueError("ModelNew supports reduction over dimension 1 only")
        return self._ext.cute_min_dim1(x)

